def transform(grid):
    h,w=len(grid),len(grid[0]); out=[row[:] for row in grid]; seen=set()
    for r in range(h):
      for c in range(w):
        col=grid[r][c]
        if col==0 or (r,c) in seen: continue
        st=[(r,c)]; seen.add((r,c)); comp=[]
        while st:
          y,x=st.pop(); comp.append((y,x))
          for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
            yy,xx=y+dy,x+dx
            if 0<=yy<h and 0<=xx<w and (yy,xx) not in seen and grid[yy][xx]==col:
              seen.add((yy,xx)); st.append((yy,xx))
        if len(comp)<4: continue
        y0=min(y for y,x in comp); y1=max(y for y,x in comp); x0=min(x for y,x in comp); x1=max(x for y,x in comp)
        area=(y1-y0+1)*(x1-x0+1)
        if len(comp)/area>=.55:
          for y in range(y0,y1+1):
            for x in range(x0,x1+1): out[y][x]=col
    # Remove residual singleton noise; restore anomalous pixels inside solid rectangles using local surrounding color.
    for r in range(h):
      for c in range(w):
        if grid[r][c]==0: continue
        same=sum(1 for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)) if 0<=r+dr<h and 0<=c+dc<w and out[r+dr][c+dc]==grid[r][c])
        if same==0: out[r][c]=0
    return out
